  async routeDoc(docId) {
    if (!docId)
      return null;
    let nbName = "", text = "";
    try {
      const info = await fetchSyncPost("/api/query/sql", { stmt: "SELECT box, content FROM blocks WHERE root_id = '" + docId + "'" });
      const rows = info && info.data || [];
      const box = rows.length ? rows[0].box : null;
      if (box) {
        const nb = await fetchSyncPost("/api/notebook", { notebook: box });
        if (nb && nb.data && nb.data.name)
          nbName = String(nb.data.name);
      }
      text = rows.map((r) => r.content || "").join(" ");
      const doc = await fetchSyncPost("/api/query/sql", { stmt: "SELECT title FROM blocks WHERE id = '" + docId + "' AND type = 'd'" });
      const d = doc && doc.data && doc.data[0];
      if (d && d.title)
        text = String(d.title) + " " + text;
    } catch (e) {
    }
    const rules = Array.isArray(this.cfg.autoRules) ? this.cfg.autoRules : [];
    if (rules.length) {
      const hayNb = nbName.toLowerCase();
      const hayText = text.toLowerCase();
      for (const rule of rules) {
        const nbHit = rule.match.find((m) => m && hayNb.includes(String(m).toLowerCase()));
        const kwHit = !nbHit && rule.match.find((m) => m && hayText.includes(String(m).toLowerCase()));
        if (!nbHit && !kwHit)
          continue;
        const vs = this.vaultList();
        const target = vs.find((v) => v.name === rule.vault);
        if (!target) {
          showMessage(this.t("autoRuleNotFound") + rule.vault);
          continue;
        }
        const ok = await this.ensureVaultUnlocked(target.i);
        if (!ok)
          return null;
        return { name: rule.vault, text };
      }
    }
    const nbVault = this.matchNotebookVault(nbName);
    if (nbVault) {
      const ok = await this.ensureVaultUnlocked(nbVault.i);
      if (!ok)
        return null;
      return { name: nbVault.name, text };
    }
    const smartVault = this.matchSmartVault(text);
    if (smartVault) {
      const ok = await this.ensureVaultUnlocked(smartVault.i);
      if (!ok)
        return null;
      if (smartVault._sim) {
        showMessage("\u{1F916} " + (this.t("smartHit") || "\u8BED\u4E49\u5206\u5E93") + " " + smartVault.name + "\uFF08" + Math.round(smartVault._sim * 100) + "% \u76F8\u4F3C\uFF09");
      }
      return { name: smartVault.name, text };
    }
    return null;
  }
