        const clsTxt = Object.keys(cls).map((k) => k + " " + cls[k]).join(" \xB7 ");
        info += "<br><span style='color:#576b95;font-weight:bold;'>\u{1F4CA} \u5206\u7C7B\uFF1A</span> " + clsTxt;
