    shareBox.appendChild(shareNote);
    box.appendChild(shareBox);
    const secBox = document.createElement("div");
    secBox.style.cssText = "border:1px solid var(--b3-border-color,#333);border-radius:6px;padding:10px;display:flex;flex-direction:column;gap:8px;";
    const secTitle = document.createElement("div");
    secTitle.style.cssText = "font-size:14px;font-weight:bold;";
    secTitle.textContent = "\u{1F512} " + this.t("secTitle");
    const idleLock = document.createElement("input");
    idleLock.className = "b3-text-field";
    idleLock.type = "number";
    idleLock.min = "0";
    idleLock.value = String(this.cfg.idleLockMin || 0);
    idleLock.style.cssText = "width:90px;";
    secBox.appendChild(mkRow(this.t("secIdleLock"), idleLock));
    const secNote = document.createElement("div");
    secNote.textContent = this.t("secNote");
    secNote.style.cssText = "font-size:12px;color:var(--b3-theme-on-background,#666);";
    secBox.appendChild(secNote);
    const deepBtn = document.createElement("button");
    deepBtn.textContent = this.t("deepCheck");
    deepBtn.className = "b3-button";
    const deepInfo = document.createElement("div");
    deepInfo.style.cssText = "font-size:12px;color:var(--b3-theme-on-background,#666);";
    deepInfo.textContent = this.t("deepHint") + "\uFF1B" + this.t("deepLast") + "\uFF1A" + (this.cfg.lastDeepCheckAt ? this.fmtTs(this.cfg.lastDeepCheckAt) : this.t("backupNone"));
    deepBtn.addEventListener("click", async () => {
      try {
        deepBtn.disabled = true;
        deepBtn.textContent = this.t("deepCheckRun");
        const r = await this.deepCheck();
        if (r.ok)
          showMessage(this.t("deepOk").replace("{0}", String(r.checked)));
        else
          showMessage(this.t("deepBad").replace("{0}", String(r.bad.length)).replace("{1}", r.bad.slice(0, 3).join("\u3001")));
        deepInfo.textContent = this.t("deepLast") + "\uFF1A" + this.fmtTs(this.cfg.lastDeepCheckAt);
      } catch (e) {
        showMessage("\u81EA\u68C0\u5931\u8D25\uFF1A" + (e && e.message ? e.message : e));
      } finally {
        deepBtn.disabled = false;
        deepBtn.textContent = this.t("deepCheck");
      }
    });
    const deepRow = document.createElement("div");
    deepRow.style.cssText = "display:flex;gap:6px;align-items:center;flex-wrap:wrap;";
    deepRow.appendChild(deepBtn);
    deepRow.appendChild(deepInfo);
    secBox.appendChild(deepRow);
    const orphanBtn = document.createElement("button");
    orphanBtn.textContent = "\u{1F6E0} " + this.t("orphanFind");
    orphanBtn.className = "b3-button";
    const orphanHint = document.createElement("div");
    orphanHint.textContent = this.t("orphanHint");
    orphanHint.style.cssText = "font-size:12px;color:var(--b3-theme-on-background,#666);";
    orphanBtn.addEventListener("click", async () => {
      try {
        orphanBtn.disabled = true;
        const n = await this.findOrphanAssets();
        if (!n)
          orphanHint.textContent = this.t("orphanNone");
      } catch (e) {
        showMessage("\u627E\u56DE\u5931\u8D25\uFF1A" + (e && e.message ? e.message : e));
      } finally {
        orphanBtn.disabled = false;
      }
    });
    const orphanRow = document.createElement("div");
    orphanRow.style.cssText = "display:flex;gap:6px;align-items:center;flex-wrap:wrap;";
    orphanRow.appendChild(orphanBtn);
    orphanRow.appendChild(orphanHint);
    secBox.appendChild(orphanRow);
    const compactBtn = document.createElement("button");
    compactBtn.textContent = "\u{1F5DC} " + this.t("compactNow");
    compactBtn.className = "b3-button";
    const compactHint = document.createElement("div");
    compactHint.textContent = this.t("compactHint");
    compactHint.style.cssText = "font-size:12px;color:var(--b3-theme-on-background,#666);";
    compactBtn.addEventListener("click", async () => {
      try {
        if (!this.isUnlocked()) {
          showMessage(this.t("unlockFirst"));
          return;
        }
        // v1.6.11: 整理库（压缩）显示动态等待
        this.setBusy(this.t("compactRun") || "\u6B63\u5728\u6574\u7406\u5BC6\u5E93\uFF08\u538B\u7F29\uFF09...");
        compactBtn.disabled = true;
        await new Promise((r) => setTimeout(r, 60));
        const before = core.fileSize(this.cfg.dbPath);
        core.compactVault(this.cfg.dbPath, this.state);
        const after = core.fileSize(this.cfg.dbPath);
        const freed = Math.round((before - after) / (1024 * 1024));
        compactHint.textContent = this.t("compactDone").replace("{0}", freed);
      } catch (e) {
        showMessage(this.t("compactFail") + (e && e.message ? e.message : e));
      } finally {
        compactBtn.disabled = false;
        this.clearBusy();
      }
    });
    const compactRow = document.createElement("div");
    compactRow.style.cssText = "display:flex;gap:6px;align-items:center;flex-wrap:wrap;";
    compactRow.appendChild(compactBtn);
    compactRow.appendChild(compactHint);
    secBox.appendChild(compactRow);
    box.appendChild(secBox);
    /* ============ v1.6.55 购买激活码（扫码点单半自动：微信支付单号对账） ============ */
    const payBox = document.createElement("div");
