    save.addEventListener("click", async () => {
      const newPath = pathInput.value.trim();
      if (!newPath) {
        showMessage(this.t("pwdEmpty"));
        return;
      }
      if (!/\.sydb$/i.test(newPath)) {
        showMessage(this.t("dbPathExtWarn") || "\u5BC6\u5E93\u6587\u4EF6\u5E94\u4F7F\u7528 .sydb \u6269\u5C55\u540D\uFF08\u5F53\u524D " + (path.extname(newPath) || "\u65E0") + "\uFF09\uFF0C\u5907\u4EFD/\u4E91\u540C\u6B65/\u5BFC\u51FA\u529F\u80FD\u5C06\u65E0\u6CD5\u6B63\u5E38\u8BC6\u522B\u8BE5\u5E93\uFF0C\u8BF7\u6539\u4E3A .sydb \u7ED3\u5C3E");
        return;
      }
      const oldPath = this.cfg.dbPath;
      this.cfg.dbPath = newPath;
      if (this.cfg.vaults && this.cfg.vaults[this.cfg.activeVault]) {
        this.cfg.vaults[this.cfg.activeVault].path = newPath;
      }
      this.cfg.autoSync = autoSync.checked;
      this.cfg.keepPlain = keepPlain.checked;
      this.cfg.includeSubDocs = subChk.checked;
      this.cfg.backupEnabled = bakEnable.checked;
      this.cfg.backupDir = bakDir.value.trim();
      this.cfg.backupIntervalMin = Math.max(1, parseInt(bakInterval.value, 10) || 360);
      this.cfg.backupKeep = Math.min(100, Math.max(1, parseInt(bakKeep.value, 10) || 10));
      this.cfg.idleLockMin = Math.max(0, parseInt(idleLock.value, 10) || 0);
      this.cfg.autoRules = this.parseAutoRules(ruleText.value);
      this.cfg.smartSplit = smartCb.checked;
      this.cfg.smartThreshold = (parseInt(thrRange.value, 10) || 5) / 100;
      this.cfg.vaultsDir = vdDir.value.trim();
      this.cfg.webdavUrl = wdUrl.value.trim();
      this.cfg.webdavUser = wdUser.value.trim();
      this.cfg.webdavPass = wdPass.value;
      this.cfg.webdavAutoSync = wdAuto.checked;
      this.cfg.webdavAutoMin = Math.max(10, parseInt(wdAutoMin.value, 10) || 30);
      /* v1.6.51 onlineUrl 已内置默认，不再从面板读取 */
      const vwEnabled = vwEnable.checked;
      this.cfg.viewerEnabled = vwEnabled;
      this.cfg.viewerPort = Math.max(1024, parseInt(vwPort.value, 10) || 18989);
      if (vwToken.value.trim().length >= 8)
        this.cfg.viewerToken = vwToken.value.trim();
      this.cfg.tamperWatch = tamperBox._chk.checked;
      this.cfg.tamperMin = Math.max(5, parseInt(tamperBox._min.value, 10) || 60);
      this.cfg.updateUrl = tamperBox._upd.value.trim() || "";
      await this.saveConfig();
      this.updateTamperBase();
      this.startTamperWatch();
      if (this.cfg.updateUrl) {
        this.checkUpdate().catch((e) => console.error("[siyuan-edb]", e));
      }
      if (vwEnabled) {
        if (!this._viewerServer)
          this.startViewerServer().catch((e) => showMessage("\u67E5\u770B\u5668\u542F\u52A8\u5931\u8D25\uFF1A" + e.message));
      } else {
        this.stopViewerServer();
      }
      if (oldPath !== newPath && this.isUnlocked()) {
        if (core.vaultExists(newPath)) {
          this.state = null;
        } else {
          this.flushVault();
        }
        this.refreshPanel();
      }
      showMessage(this.t("settingSaved"));
    });
